w9m4.solucao:
def numerar(itens):
    return [f"{i}. {item}" for i, item in enumerate(itens, start=1)]


def boletim(nomes, notas):
    return dict(zip(nomes, notas))


def evolucao(antes, depois):
    return [d - a for a, d in zip(antes, depois)]


print(numerar(["pão", "leite", "ovos"]))
print(boletim(["Ana", "Caio"], [9, 7]))
print(evolucao([10, 20, 15], [12, 20, 25]))

