w9m6.solucao:
def bateu_recorde(pontos, recorde):
    return any([p > recorde for p in pontos])


def todos_passaram(pontos, meta):
    return all([p >= meta for p in pontos])


def sem_zeros(pontos):
    return list(filter(lambda p: p != 0, pontos))


print(bateu_recorde([10, 0, 25, 7], 20))
print(todos_passaram([10, 0, 25, 7], 5))
print(sem_zeros([10, 0, 25, 7]))

