w9m8.solucao:
def ordenar(jogadores):
    return sorted(jogadores, key=lambda j: (-j[1], j[0]))


def mostrar_ranking(jogadores):
    posicao = 0
    ultimo = None
    for i, (nome, pontos) in enumerate(ordenar(jogadores), start=1):
        if pontos != ultimo:
            posicao = i
            ultimo = pontos
        print(f"{posicao}. {nome} - {pontos} pts")


mostrar_ranking([("Duda", 40), ("Caio", 50), ("Bia", 40), ("Ana", 30)])
